package sidecar

import (
	"encoding/json"
	"fmt"
	"hash/crc32"
	"io"
	"os"
)

// TypeCastagnoli identifies the Castagnoli CRC32 algorithm.
const TypeCastagnoli = "castagnoli"

var castagnoliTable = crc32.MakeTable(crc32.Castagnoli)

// Sidecar represents a CRC sidecar record for a snapshot data file.
type Sidecar struct {
	// CRC is the lowercase hex-encoded checksum value.
	CRC string `json:"crc"`

	// Type is the algorithm type identifier (e.g. TypeCastagnoli).
	Type string `json:"type"`

	// Disabled indicates whether integrity checking is disabled.
	Disabled bool `json:"disabled,omitempty"`
}

// NewCastagnoli returns a Sidecar for the given Castagnoli CRC32 checksum. The
// CRC field is set to the lowercase 8-character hex representation of crc, the
// Type field is set to TypeCastagnoli, and Disabled is set to false.
func NewCastagnoli(crc uint32) *Sidecar {
	return &Sidecar{
		CRC:      fmt.Sprintf("%08x", crc),
		Type:     TypeCastagnoli,
		Disabled: false,
	}
}

// CRC32 parses the CRC field and returns it as a uint32. It returns an error if
// the Type is not a recognized algorithm, or if the CRC is not exactly 8 valid
// lowercase hexadecimal characters.
func (s *Sidecar) CRC32() (uint32, error) {
	if s.Type != TypeCastagnoli {
		return 0, fmt.Errorf("unknown sidecar type: %q", s.Type)
	}
	if s.CRC == "" {
		return 0, fmt.Errorf("empty CRC")
	}
	if len(s.CRC) != 8 {
		return 0, fmt.Errorf("invalid CRC length: %d, expected 8", len(s.CRC))
	}

	var sum uint32
	for i := 0; i < len(s.CRC); i++ {
		c := s.CRC[i]
		var v uint32
		switch {
		case c >= '0' && c <= '9':
			v = uint32(c - '0')
		case c >= 'a' && c <= 'f':
			v = uint32(c-'a') + 10
		default:
			return 0, fmt.Errorf("invalid CRC character: %q", c)
		}
		sum = sum<<4 | v
	}
	return sum, nil
}

// WriteFile writes a sidecar file to path as a JSON object containing a "crc"
// field (the lowercase 8-character hex representation of sum) and a "type"
// field (set to "castagnoli"). It returns a non-nil error on any I/O failure.
func WriteFile(path string, sum uint32) error {
	b, err := json.Marshal(NewCastagnoli(sum))
	if err != nil {
		return err
	}
	return os.WriteFile(path, b, 0644)
}

// ReadFile reads and JSON-unmarshals the sidecar file at path into a *Sidecar.
// It returns a non-nil error if the file does not exist or if its contents are
// not valid JSON.
func ReadFile(path string) (*Sidecar, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	s := &Sidecar{}
	if err := json.Unmarshal(b, s); err != nil {
		return nil, err
	}
	return s, nil
}

// ReadCRC32File reads the sidecar file at path and returns the stored CRC32 as
// a uint32. It returns a non-nil error if the file cannot be read or if the
// Type field is not a recognized algorithm.
func ReadCRC32File(path string) (uint32, error) {
	s, err := ReadFile(path)
	if err != nil {
		return 0, err
	}
	return s.CRC32()
}

// CompareFile computes the CRC32 of the data file at dataPath, reads the
// sidecar file at sidecarPath, and compares the two checksums. It returns
// (true, nil) when they match, (false, nil) when they do not, and a non-nil
// error when either file cannot be read or parsed.
func CompareFile(dataPath, sidecarPath string) (bool, error) {
	sum, err := crc32File(dataPath)
	if err != nil {
		return false, err
	}
	want, err := ReadCRC32File(sidecarPath)
	if err != nil {
		return false, err
	}
	return sum == want, nil
}

